CREATE TABLE IF NOT EXISTS stops (stop_id TEXT PRIMARY KEY,name TEXT NOT NULL,latitude DOUBLE PRECISION NOT NULL,longitude DOUBLE PRECISION NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_stops_location ON stops(latitude,longitude);
CREATE TABLE IF NOT EXISTS routes (route_id TEXT PRIMARY KEY,short_name TEXT,long_name TEXT,route_color TEXT,route_text_color TEXT,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE routes ADD COLUMN IF NOT EXISTS route_color TEXT;
ALTER TABLE routes ADD COLUMN IF NOT EXISTS route_text_color TEXT;
CREATE TABLE IF NOT EXISTS route_stops (route_id TEXT NOT NULL REFERENCES routes(route_id) ON DELETE CASCADE,stop_id TEXT NOT NULL REFERENCES stops(stop_id) ON DELETE CASCADE,stop_sequence INTEGER NOT NULL,PRIMARY KEY(route_id,stop_id));
CREATE INDEX IF NOT EXISTS idx_route_stops_stop ON route_stops(stop_id);
CREATE TABLE IF NOT EXISTS vehicle_positions (vehicle_id TEXT PRIMARY KEY,route_id TEXT,stop_id TEXT,latitude DOUBLE PRECISION NOT NULL,longitude DOUBLE PRECISION NOT NULL,bearing DOUBLE PRECISION,speed_mps DOUBLE PRECISION,observed_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_vehicle_positions_route ON vehicle_positions(route_id);
CREATE INDEX IF NOT EXISTS idx_vehicle_positions_observed ON vehicle_positions(observed_at);
